import type{PoolClient}from'pg';import{sha256Canonical}from'../core/hash.js';import{replayAll}from'../replay/replay.service.js';
import{migrationManifest,dependencyLockEvidence}from'./artifact-integrity.js';

async function add(c:PoolClient,checkRun:string,build:string,code:string,status:'PASS'|'FAIL'|'NOT_EXECUTED',evidence:any,checked=0,failed=0,expected:any={},actual:any={}){
 await c.query(`INSERT INTO zsl.zsl3_runtime_checks(runtime_check_run_id,build_run_id,check_code,status,checked_count,failed_count,expected_value,actual_value,evidence,evidence_sha256)
 VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,$9::jsonb,$10)`,
 [checkRun,build,code,status,checked,failed,JSON.stringify(expected),JSON.stringify(actual),JSON.stringify(evidence),sha256Canonical(evidence)]);
}
function pass(b:boolean){return b?'PASS' as const:'FAIL' as const}
export async function runChecks(c:PoolClient,run:string,p:any):Promise<string>{
 const br=(await c.query<any>(`SELECT * FROM zsl.zsl3_build_runs WHERE build_run_id=$1`,[run])).rows[0];if(!br)throw new Error('ZSL3_BUILD_NOT_FOUND');
 const cr=await c.query<any>(`INSERT INTO zsl.zsl3_runtime_check_runs(build_run_id,package_sha256,policy_sha256,status,evidence,evidence_sha256)
 VALUES($1,$2,$3,'RUNNING','{}'::jsonb,$4) RETURNING runtime_check_run_id::text`,[run,br.package_sha256,p.hashes.certification,sha256Canonical({})]);
 const checkRun=cr.rows[0].runtime_check_run_id;
 let anyFail=false;
 const emit=async(code:string,ok:boolean,evidence:any,checked=1,failed=ok?0:1,expected:any={},actual:any={})=>{if(!ok)anyFail=true;await add(c,checkRun,run,code,pass(ok),evidence,checked,failed,expected,actual)};
 const binds=(await c.query<any>(`SELECT * FROM zsl.zsl3_source_bindings WHERE build_run_id=$1`,[run])).rows;
 const z1m=binds.filter((b:any)=>b.upstream_package_sha256!==p.upstream.zsl1.sha256);await emit('exact_zsl1_package',binds.length>0&&z1m.length===0,{bindings:binds.map((b:any)=>({role:b.release_role,ingestRunId:b.ingest_run_id,actual:b.upstream_package_sha256,expected:p.upstream.zsl1.sha256,match:b.upstream_package_sha256===p.upstream.zsl1.sha256}))},binds.length,z1m.length,{sha:p.upstream.zsl1.sha256},{mismatches:z1m.length});
 let z2:any=null;try{z2=(await c.query<any>(`SELECT a.normalization_run_id::text,a.certification_run_id::text,n.package_sha256,n.engine_version FROM zsl.zsl2_current_authority a JOIN zsl.zsl2_normalization_runs n ON n.normalization_run_id=a.normalization_run_id WHERE a.normalization_run_id=$1 AND a.certification_run_id=$2 LIMIT 1`,[br.zsl2_normalization_run_id,br.zsl2_certification_run_id])).rows[0]}catch(e:any){}
 const z2ok=!!z2&&z2.package_sha256===p.upstream.zsl2.sha256&&z2.engine_version===p.upstream.zsl2.engineVersion;
 await emit('exact_zsl2_package',z2ok,{boundNormalizationRun:br.zsl2_normalization_run_id,boundCertificationRun:br.zsl2_certification_run_id,row:z2??null},1,z2ok?0:1,{sha:p.upstream.zsl2.sha256,engine:p.upstream.zsl2.engineVersion},{sha:z2?.package_sha256??null,engine:z2?.engine_version??null});
 const valid=(await c.query<{ok:boolean}>(`SELECT zsl.zsl3_bindings_still_valid($1) ok`,[run])).rows[0]?.ok===true;
 await emit('zsl1_bindings_current',valid,{bindingsCurrent:valid});await emit('zsl2_authority_current',valid,{zsl2Current:valid});
 await emit('source_policy_sha_match',br.source_policy_sha256===p.hashes.source,{stored:br.source_policy_sha256,actual:p.hashes.source});
 const ds:Record<string,Set<string>>={};for(const b of binds)(ds[b.source_dataset]??=new Set()).add(String(b.source_year??b.source_vintage));
 const acsOk=(ds.ACS?.size??0)<=1,beaOk=(ds.BEA_RPP?.size??0)<=1;
 const cbp=[...(ds.CBP??new Set())],zbp=[...(ds.ZBP??new Set())];const bizOk=!cbp.length||!zbp.length||cbp[0]===zbp[0];
 await emit('source_vintage_coherence',acsOk&&beaOk&&bizOk,{ACS:[...(ds.ACS??new Set())],BEA_RPP:[...(ds.BEA_RPP??new Set())],CBP:cbp,ZBP:zbp});
 const expectedMd=binds.filter((b:any)=>b.source_dataset==='ACS').length*p.feature.acsVariableBindings.length;
 const mds=(await c.query<any>(`SELECT * FROM zsl.zsl3_acs_variable_metadata WHERE build_run_id=$1`,[run])).rows;
 await emit('acs_metadata_complete',mds.length===expectedMd,{expected:expectedMd,actual:mds.length},expectedMd,Math.abs(expectedMd-mds.length));
 let semanticBad=0;const sem:any[]=[];for(const m of mds){const v=p.feature.acsVariableBindings.find((x:any)=>x.variableCode===m.variable_code);let ok=!!v;
   if(v?.expectedLabelContains)ok=ok&&String(m.label).toLowerCase().includes(String(v.expectedLabelContains).toLowerCase());
   if(v?.expectedConceptContains)ok=ok&&String(m.concept??'').toLowerCase().includes(String(v.expectedConceptContains).toLowerCase());
   if(v?.expectedPredicateType)ok=ok&&String(m.predicate_type??'')===String(v.expectedPredicateType);
   if(!ok)semanticBad++;sem.push({variable:m.variable_code,geographies:m.geography_applicability,ok});
 }await emit('acs_metadata_semantic_match',mds.length===expectedMd&&semanticBad===0,{variables:sem},mds.length,semanticBad);
 const zipBad=Number((await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_source_facts WHERE build_run_id=$1 AND source_role='ZBP' AND geography_scope<>'POSTAL_CODE'`,[run])).rows[0].n);await emit('zip_zcta_separation',zipBad===0,{violations:zipBad},zipBad,zipBad);await emit('zbp_postal_resolution',zipBad===0,{violations:zipBad},zipBad,zipBad);
 const msaBinding=binds.find((b:any)=>b.source_dataset==='BEA_RPP'&&b.source_geography==='MSA');
 let msaObs=0,msaRec=0,msaUnresolved=0;if(msaBinding){msaObs=Number((await c.query<any>(`SELECT count(*) n FROM zsl.release_record_memberships WHERE release_id=$1 AND ingest_run_id=$2`,[msaBinding.release_id,msaBinding.ingest_run_id])).rows[0].n);const rr=await c.query<any>(`SELECT count(*) n,count(*) FILTER(WHERE mapping_status IN('PENDING_ZSL2_AUTHORITY','UNRESOLVED','REJECTED')) bad FROM zsl.zsl3_bea_msa_reconciliation WHERE build_run_id=$1`,[run]);msaRec=Number(rr.rows[0].n);msaUnresolved=Number(rr.rows[0].bad)}
 await emit('bea_msa_reconciliation_complete',!msaBinding||msaObs===msaRec,{observed:msaObs,reconciled:msaRec,sourceRequired:false},msaObs,Math.abs(msaObs-msaRec));
 await emit('bea_msa_authority_valid',!msaBinding||msaUnresolved===0,{observed:msaObs,unresolved:msaUnresolved},msaObs,msaUnresolved);
 const biz=(await c.query<any>(`SELECT b.*,f.source_role FROM zsl.zsl3_business_activity_facts b JOIN zsl.zsl3_source_facts f ON f.fact_id=b.fact_id WHERE f.build_run_id=$1`,[run])).rows;
 const allowed=new Map<string,Set<string>>();for(const g of p.naics.featureGroups){const s=allowed.get(g.targetVocabulary)??new Set<string>();for(const code of g.codes)s.add(String(code));allowed.set(g.targetVocabulary,s)}
 let vocabBad=0,crossBad=0;for(const b of biz){if(!allowed.has(b.source_naics_vocabulary))vocabBad++;if(b.source_naics_vocabulary!==b.normalized_naics_vocabulary){const q=await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_naics_crosswalks WHERE build_run_id=$1 AND source_vocabulary=$2 AND target_vocabulary=$3 AND source_code=$4 AND certified`,[run,b.source_naics_vocabulary,b.normalized_naics_vocabulary,b.naics_code]);if(Number(q.rows[0].n)===0)crossBad++}}
 await emit('naics_vocabulary_valid',vocabBad===0,{facts:biz.length,invalid:vocabBad},biz.length,vocabBad);
 await emit('naics_crosswalk_valid',crossBad===0,{crosswalkRequired:biz.filter((b:any)=>b.source_naics_vocabulary!==b.normalized_naics_vocabulary).length,invalid:crossBad},biz.length,crossBad);
 const facts=Number((await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_source_facts WHERE build_run_id=$1`,[run])).rows[0].n),fl=Number((await c.query<any>(`SELECT count(DISTINCT fact_id) n FROM zsl.zsl3_fact_lineage WHERE build_run_id=$1`,[run])).rows[0].n);await emit('raw_fact_lineage_100',facts>0&&facts===fl,{facts,lineage:fl},facts,Math.max(0,facts-fl));
 const df=Number((await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_derived_features WHERE build_run_id=$1`,[run])).rows[0].n),dfl=Number((await c.query<any>(`SELECT count(DISTINCT derived_feature_id) n FROM zsl.zsl3_feature_lineage WHERE build_run_id=$1`,[run])).rows[0].n);await emit('derived_feature_lineage_100',df>0&&df===dfl,{derived:df,lineage:dfl},df,Math.max(0,df-dfl));
 const defs=(await c.query<any>(`SELECT feature_code,formula_sha256 FROM zsl.zsl3_feature_definitions WHERE build_run_id=$1 AND enabled`,[run])).rows;await emit('feature_definition_coverage_100',defs.length===p.feature.derivedDefinitions.length,{actual:defs.map((x:any)=>x.feature_code),expected:p.feature.derivedDefinitions.map((x:any)=>x.featureCode)},p.feature.derivedDefinitions.length,Math.abs(defs.length-p.feature.derivedDefinitions.length));await emit('formula_sha_coverage_100',defs.length>0&&defs.every((x:any)=>/^[0-9a-f]{64}$/.test(x.formula_sha256)),{count:defs.length},defs.length,defs.filter((x:any)=>!/^[0-9a-f]{64}$/.test(x.formula_sha256)).length);
 const rep=await replayAll(c,run,p);await emit('deterministic_formula_replay_100',rep.feature.checked>0&&rep.feature.failed===0,rep.feature,rep.feature.checked,rep.feature.failed);await emit('percentile_replay_100',rep.percentile.checked>0&&rep.percentile.failed===0,rep.percentile,rep.percentile.checked,rep.percentile.failed);await emit('snapshot_hash_replay_100',rep.snapshot.checked>0&&rep.snapshot.failed===0,rep.snapshot,rep.snapshot.checked,rep.snapshot.failed);await emit('freshness_replay_100',rep.freshness.checked>0&&rep.freshness.failed===0,rep.freshness,rep.freshness.checked,rep.freshness.failed);await emit('confidence_replay_100',rep.confidence.checked>0&&rep.confidence.failed===0,rep.confidence,rep.confidence.checked,rep.confidence.failed);await emit('missingness_replay_100',rep.missingness.checked>0&&rep.missingness.failed===0,rep.missingness,rep.missingness.checked,rep.missingness.failed);
 const snaps=(await c.query<any>(`SELECT s.*,upper(l.location_type) location_type FROM zsl.zsl3_geographic_feature_snapshots s JOIN zsl.locations l ON l.location_id=s.location_id WHERE s.build_run_id=$1`,[run])).rows;
 const srcCovBad=snaps.filter((s:any)=>Number(s.required_sources_present)<Number(s.required_sources_expected)).length;await emit('source_coverage_valid',snaps.length>0&&srcCovBad===0,{snapshots:snaps.length,violations:srcCovBad},snaps.length,srcCovBad);
 const sfBad=snaps.filter((s:any)=>Number(s.actual_source_fact_count)<Number(s.expected_source_fact_count)).length;await emit('source_fact_coverage_valid',snaps.length>0&&sfBad===0,{violations:sfBad},snaps.length,sfBad);
 const dfBad=snaps.filter((s:any)=>Number(s.actual_derived_feature_count)<Number(s.expected_derived_feature_count)).length;await emit('derived_feature_coverage_valid',snaps.length>0&&dfBad===0,{violations:dfBad},snaps.length,dfBad);
 const locBad=snaps.filter((s:any)=>Number(s.location_coverage_pct)<Number(p.source.locationCoverageMinimumPct?.[s.location_type]??0)).length;await emit('location_coverage_valid',snaps.length>0&&locBad===0,{snapshots:snaps.length,violations:locBad,minimums:p.source.locationCoverageMinimumPct},snaps.length,locBad);
 const fatal=Number((await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_conflicts WHERE build_run_id=$1 AND severity='FATAL'`,[run])).rows[0].n);await emit('zero_unresolved_fatal_conflicts',fatal===0,{fatal},fatal,fatal);
 const orph=Number((await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_source_facts f LEFT JOIN zsl.certified_canonical_locations l ON l.location_id=f.location_id WHERE f.build_run_id=$1 AND l.location_id IS NULL`,[run])).rows[0].n);await emit('zero_orphan_location_mappings',orph===0,{orphans:orph},facts,orph);
 const pctRows=(await c.query<any>(`SELECT d.derived_feature_id,d.feature_code,d.source_vintage_set,l.location_type FROM zsl.zsl3_derived_features d JOIN zsl.locations l ON l.location_id=d.location_id JOIN zsl.zsl3_feature_definitions fd ON fd.feature_definition_id=d.feature_definition_id WHERE d.build_run_id=$1 AND fd.formula_type='PERCENT_RANK'`,[run])).rows;let pctBad=0;for(const d of pctRows){const src=d.feature_code==='purchasing_power_index'?'real_median_household_income_index':'retail_density_per_100k';const q=await c.query<any>(`SELECT count(*) n FROM zsl.zsl3_derived_features x JOIN zsl.locations l ON l.location_id=x.location_id WHERE x.build_run_id=$1 AND x.feature_code=$2 AND l.location_type=$3 AND x.source_vintage_set=$4::jsonb`,[run,src,d.location_type,JSON.stringify(d.source_vintage_set)]);if(Number(q.rows[0].n)<p.feature.minimumPercentileCohortSize)pctBad++}await emit('percentile_sample_protection',pctBad===0,{percentileFeatures:pctRows.length,violations:pctBad,minimum:p.feature.minimumPercentileCohortSize},pctRows.length,pctBad);
 const sup=await c.query<any>(`SELECT count(*) total,count(*) FILTER(WHERE (b.establishment_flag IS NOT NULL AND b.establishment_flag<>'') AND NOT(f.missingness_state='SUPPRESSED' AND b.establishment_count IS NULL)) bad FROM zsl.zsl3_business_activity_facts b JOIN zsl.zsl3_source_facts f ON f.fact_id=b.fact_id WHERE f.build_run_id=$1` ,[run]);await emit('suppression_handling',Number(sup.rows[0].bad)===0,{checked:Number(sup.rows[0].total),violations:Number(sup.rows[0].bad)},Number(sup.rows[0].total),Number(sup.rows[0].bad));
 const forbidden=p.source.forbiddenEvidenceClasses??[];const leak=Number((await c.query<any>(`SELECT count(*) n FROM(SELECT evidence_class FROM zsl.zsl3_source_facts WHERE build_run_id=$1 UNION ALL SELECT evidence_class FROM zsl.zsl3_derived_features WHERE build_run_id=$1 UNION ALL SELECT evidence_class FROM zsl.zsl3_geographic_feature_snapshot_values WHERE build_run_id=$1)x WHERE evidence_class=ANY($2::text[])`,[run,forbidden])).rows[0].n);await emit('no_model_prior_leakage',leak===0,{forbidden,violations:leak},facts+df,leak);
 await emit('package_sha_match',br.package_sha256===process.env.ZSL3_PACKAGE_SHA256,{stored:br.package_sha256,runtime:process.env.ZSL3_PACKAGE_SHA256??null});await emit('git_sha_present',!!br.git_sha,{gitSha:br.git_sha});
 const mm=migrationManifest();await emit('migration_manifest_match',mm.sha256===br.migration_manifest_sha256,{actual:mm.sha256,expected:br.migration_manifest_sha256,files:mm.entries},mm.entries.length,mm.sha256===br.migration_manifest_sha256?0:1);
 const dl=dependencyLockEvidence();await emit('dependency_lock_valid',dl.ok&&dl.sha256===br.dependency_tree_sha256,{lock:dl,expected:br.dependency_tree_sha256},1,dl.ok&&dl.sha256===br.dependency_tree_sha256?0:1);
 const rbac=await c.query<any>(`SELECT count(*) FILTER(WHERE grantee='PUBLIC' AND privilege_type IN('INSERT','UPDATE','DELETE','TRUNCATE')) public_mutations,count(*) FILTER(WHERE grantee IN('anon','authenticated') AND privilege_type IN('INSERT','UPDATE','DELETE','TRUNCATE')) app_mutations FROM information_schema.role_table_grants WHERE table_schema='zsl' AND table_name LIKE 'zsl3_%'`);const rbacBad=Number(rbac.rows[0].public_mutations)+Number(rbac.rows[0].app_mutations);await emit('rbac_verified',rbacBad===0,{catalog:rbac.rows[0]},1,rbacBad);
 const roll=(await c.query<any>(`SELECT * FROM zsl.zsl3_qa_evidence WHERE build_run_id=$1 AND evidence_code='ROLLBACK_VERIFIED' ORDER BY created_at DESC LIMIT 1`,[run])).rows[0];await add(c,checkRun,run,'rollback_verified',roll?(roll.status==='PASS'?'PASS':'FAIL'):'NOT_EXECUTED',roll?.evidence??{reason:'QA_ROLLBACK_EVIDENCE_MISSING'},roll?1:0,roll?.status==='FAIL'?1:0,{required:true},{status:roll?.status??'NOT_EXECUTED'});if(!roll||roll.status!=='PASS')anyFail=true;
 const summary={buildRunId:run,checksAt:new Date().toISOString(),failed:anyFail};await c.query(`UPDATE zsl.zsl3_runtime_check_runs SET completed_at=now(),status=$2,evidence=$3::jsonb,evidence_sha256=$4 WHERE runtime_check_run_id=$1`,[checkRun,anyFail?'FAIL':'PASS',JSON.stringify(summary),sha256Canonical(summary)]);
 return checkRun;
}
